const SliderContext = SliderPrimitive.Context;
const SliderHiddenInput = SliderPrimitive.HiddenInput;

export {
  Slider,
  SliderContext,
  SliderControl,
  SliderDraggingIndicator,
  SliderHiddenInput,
  SliderLabel,
  SliderMarker,
  SliderMarkerGroup,
  SliderRange,
  SliderRootProvider,
  SliderThumb,
  SliderThumbs,
  SliderTrack,
  SliderValueText,
  useSlider,
  useSliderContext,
};
export type {
  SliderContextProps,
  SliderControlProps,
  SliderDraggingIndicatorProps,
  SliderFocusChangeDetails,
  SliderHiddenInputProps,
  SliderLabelProps,
  SliderMarkerGroupProps,
  SliderMarkerProps,
  SliderRangeProps,
  SliderRootProps,
  SliderRootProviderProps,
  SliderThumbProps,
  SliderTrackProps,
  SliderValueChangeDetails,
  SliderValueTextProps,
  UseSliderContext,
  UseSliderProps,
  UseSliderReturn,
} from '@ark-ui/solid/slider';

@layer moduix.components {
  .root {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: var(--moduix-spacing-2);
    width: 100%;

    &[data-orientation='vertical'] {
      grid-template-areas:
        'label value'
        'control markers';
      grid-template-columns: auto max-content;
      grid-template-rows: auto minmax(0, 1fr);
      align-items: center;
      width: max-content;
      height: 12rem;

      & .label {
        grid-area: label;
      }

      & .valueText {
        grid-area: value;
      }

      & .control {
        grid-area: control;
      }

      & .markerGroup {
        grid-area: markers;
      }
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .label,
  .valueText {
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .valueText {
    justify-self: end;
    text-align: end;
  }

  .control {
    display: flex;
    grid-column: 1 / -1;
    align-items: center;
    min-height: var(--moduix-spacing-5);
    cursor: pointer;

    &[data-orientation='vertical'] {
      flex-direction: column;
      width: var(--moduix-spacing-5);
      height: 100%;
      min-height: 0;
    }

    &[data-disabled],
    .root[data-readonly] & {
      cursor: default;
    }
  }

  .track {
    flex: 1;
    height: var(--moduix-slider-track-size, var(--moduix-spacing-1-5));
    overflow: hidden;
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-slider-track-bg, var(--moduix-color-muted));
    box-shadow: inset 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-border);

    &[data-orientation='vertical'] {
      width: var(--moduix-slider-track-size, var(--moduix-spacing-1-5));
      height: 100%;
    }

    &[data-invalid] {
      box-shadow: inset 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-destructive);
    }
  }

  .range {
    height: 100%;
    border-radius: inherit;
    background-color: var(--moduix-slider-range-bg, var(--moduix-color-primary));

    &[data-orientation='vertical'] {
      width: 100%;
    }

    &[data-invalid] {
      background-color: var(--moduix-color-destructive);
    }
  }

  .thumb {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-slider-thumb-size, var(--moduix-spacing-4));
    height: var(--moduix-slider-thumb-size, var(--moduix-spacing-4));
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-color-background);
    box-shadow: var(--moduix-shadow-sm);
    outline: 0;
    transition:
      border-color var(--moduix-transition-default),
      box-shadow var(--moduix-transition-default);

    &:focus-visible {
      border-color: var(--moduix-color-ring);
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width) var(--moduix-color-ring);
    }

    &[data-dragging] {
      border-color: var(--moduix-color-ring);
      box-shadow:
        0 0 0 var(--moduix-focus-ring-inset-width) var(--moduix-color-ring),
        var(--moduix-shadow-md);
    }

    &[data-invalid] {
      border-color: var(--moduix-color-destructive);

      &:focus-visible {
        box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width) var(--moduix-color-destructive);
      }
    }
  }

  /* Ark positions the indicator along the track; moduix only moves it off the thumb. */
  .draggingIndicator {
    padding: var(--moduix-spacing-1) var(--moduix-spacing-2);
    border-radius: var(--moduix-radius-sm);
    background-color: var(--moduix-color-foreground);
    color: var(--moduix-color-background);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-medium);
    line-height: 1;
    white-space: nowrap;
    pointer-events: none;

    &[data-orientation='horizontal'] {
      inset-block-end: 100%;
      margin-block-end: var(--moduix-spacing-2);
    }

    &[data-orientation='vertical'] {
      inset-inline-start: 100%;
      margin-inline-start: var(--moduix-spacing-2);
    }
  }

  /* Ark positions markers absolutely, so the group reserves one line for their labels. */
  .markerGroup {
    grid-column: 1 / -1;
    min-height: var(--moduix-line-height-text-xs);
    margin-block-start: var(--moduix-spacing-2);

    &[data-orientation='vertical'] {
      height: 100%;
      margin: 0;
    }
  }

  .marker {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);

    /* Logical margins center the dot in both writing directions. */
    &::before {
      position: absolute;
      inset-block-start: calc(-1 * var(--moduix-spacing-2));
      inset-inline-start: 50%;
      width: var(--moduix-spacing-1);
      height: var(--moduix-spacing-1);
      margin-inline-start: calc(-0.5 * var(--moduix-spacing-1));
      border-radius: var(--moduix-radius-full);
      background-color: var(--moduix-color-border);
      content: '';
    }

    &:is([data-state='under-value'], [data-state='at-value'])::before {
      background-color: var(--moduix-slider-range-bg, var(--moduix-color-primary));
    }

    .root[data-invalid] &:is([data-state='under-value'], [data-state='at-value'])::before {
      background-color: var(--moduix-color-destructive);
    }

    &[data-orientation='vertical']::before {
      inset-block-start: 50%;
      inset-inline-start: calc(-1 * var(--moduix-spacing-2));
      margin-block-start: calc(-0.5 * var(--moduix-spacing-1));
    }
  }
}
